  // taxable = 95000 - 2375 = 92625
  // VAT = 92625 × 21 / 100 = 19451.25 → 19451 (banker's rounding)
  // total = 95000 - 2375 + 19451 = 112076
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 19451);
  assert.equal(totals.total, 112076);
});

